def _la_list(node: "TkvNode", scope: "Scope") -> "i32":
    """True neu node la bien kieu `list[dtype]` (tensor cua repo inference)."""
    if ekind(node) != 'var':
        return 0
    try:
        ta = scope.tra(ea_str(node)).ta
    except Exception:
        return 0
    if ta.shape_ten == 'list' and ta.dtype in ('f32', 'f64', 'i32', 'i64'):
        return 1
    return 0


def _dtype_mang(node: "TkvNode", scope: "Scope", ten_ham: "str") -> "str":
    """dtype phan tu cua bien MANG rank 1 (f32/f64/i32/i64); loi ro neu khong dung.

    2026-10-17: chap nhan ca MANG (`ta.dims`) va `list[dtype]` - kieu tensor
    chuan cua repo inference la `list[f32]`, truoc day bi tu choi o day nen
    SIMD khong dung duoc repo do du B-04 da ship DLL.
    """
    if ekind(node) != 'var':
        raise SyntaxError("il_codegen: " + ten_ham + "() nhan BIEN mang rank 1 (vd np.zeros(n, dtype=np.float32)), gap bieu thuc")
    ta = scope.tra(ea_str(node)).ta
    la_mang = False
    if ta.dims and len(ta.dims) == 1:
        la_mang = True
    elif ta.shape_ten == 'list':
        la_mang = True
    if not la_mang or ta.dtype not in ('f32', 'f64', 'i32', 'i64'):
        raise SyntaxError(
            "il_codegen: " + ten_ham + "(" + ea_str(node) + ") can mang rank 1 kieu f32/f64/i32/i64 "
            "(hoac list[f32]/list[f64]/list[i32]/list[i64]), "
            "'" + ea_str(node) + "' co dtype=" + str(ta.dtype) + " shape=" + ta.shape_str())
    return ta.dtype


def _dtype_tra_ve(args: "list[TkvNode]", scope: "Scope", func_table: "dict[str,TkvSig]") -> "str":
    if len(args) >= 1 and ekind(args[0]) == 'var':
        try:
            ta = scope.tra(ea_str(args[0])).ta
        except KeyError:
            return 'f64'
        if ta.dims and len(ta.dims) == 1 and ta.dtype in ('f32', 'f64', 'i32', 'i64'):
            return ta.dtype
    return 'f64'


def _nap_mang(node: "TkvNode", scope: "Scope", out: "list[str]", ctx: "Ctx"):
